package main

import "fmt"

func main() {
	var n, m int
	fmt.Scan(&n, &m)
	broken := map[int]bool{}
	for i := 0; i < m; i++ {
		var step int
		fmt.Scan(&step)
		broken[step] = true
	}

	dp := make([]int, n+1)
	dp[0] = 1
	for i := 1; i <= n; i++ {
		if broken[i] {
			continue // no way to land here, so dp[i] stays 0
		}
		dp[i] = dp[i-1]
		if i >= 2 {
			dp[i] += dp[i-2]
		}
	}
	fmt.Println("ways:", dp[n])
}

