package main

import "fmt"

func maxInt(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func rob(houses []int) int {
	if len(houses) == 0 {
		return 0
	}
	dp := make([]int, len(houses)+1)
	dp[1] = houses[0]
	for i := 2; i <= len(houses); i++ {
		dp[i] = maxInt(dp[i-1], dp[i-2]+houses[i-1])
	}
	return dp[len(houses)]
}

func main() {
	var n int
	fmt.Scan(&n)
	houses := make([]int, n)
	for i := range houses {
		fmt.Scan(&houses[i])
	}
	fmt.Println("best:", rob(houses))
}

