package main

import "fmt"

func main() {
	var n int
	fmt.Scan(&n)
	coins := make([]int, n)
	for i := range coins {
		fmt.Scan(&coins[i])
	}
	var q int
	fmt.Scan(&q)
	amounts := make([]int, q)
	biggest := 0
	for i := range amounts {
		fmt.Scan(&amounts[i])
		if amounts[i] > biggest {
			biggest = amounts[i]
		}
	}

	impossible := biggest + 1
	dp := make([]int, biggest+1)
	for a := 1; a <= biggest; a++ {
		dp[a] = impossible
		for _, c := range coins {
			if c <= a && dp[a-c]+1 < dp[a] {
				dp[a] = dp[a-c] + 1
			}
		}
	}

	for _, a := range amounts {
		if dp[a] == impossible {
			fmt.Printf("%d is impossible\n", a)
		} else {
			fmt.Printf("%d needs %d\n", a, dp[a])
		}
	}
}

