package main

import "fmt"

func main() {
	var rows, cols int
	fmt.Scan(&rows, &cols)
	grid := make([]string, rows)
	for r := range grid {
		fmt.Scan(&grid[r])
	}

	dp := make([][]int, rows)
	for r := range dp {
		dp[r] = make([]int, cols)
	}
	for r := 0; r < rows; r++ {
		for c := 0; c < cols; c++ {
			if grid[r][c] == '#' {
				continue
			}
			if r == 0 && c == 0 {
				dp[r][c] = 1
				continue
			}
			if r > 0 {
				dp[r][c] += dp[r-1][c]
			}
			if c > 0 {
				dp[r][c] += dp[r][c-1]
			}
		}
	}
	fmt.Println("paths:", dp[rows-1][cols-1])
}

