package main

import "fmt"

func minInt(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func main() {
	var rows, cols int
	fmt.Scan(&rows, &cols)
	cost := make([][]int, rows)
	dp := make([][]int, rows)
	for r := range cost {
		cost[r] = make([]int, cols)
		dp[r] = make([]int, cols)
		for c := range cost[r] {
			fmt.Scan(&cost[r][c])
		}
	}
	for r := 0; r < rows; r++ {
		for c := 0; c < cols; c++ {
			switch {
			case r == 0 && c == 0:
				dp[r][c] = cost[r][c]
			case r == 0:
				dp[r][c] = cost[r][c] + dp[r][c-1]
			case c == 0:
				dp[r][c] = cost[r][c] + dp[r-1][c]
			default:
				dp[r][c] = cost[r][c] + minInt(dp[r-1][c], dp[r][c-1])
			}
		}
	}
	fmt.Println("cheapest:", dp[rows-1][cols-1])
}
